-- =====================================================================
-- Baza de date UNIVERSITATE (exemplul 3, cel mai mare)
-- O universitate fictivă: facultăți, specializări, profesori, discipline,
-- studenți și notele lor din anii de studiu încheiați.
-- Motor: SQLite (se rulează în DBeaver: Execute SQL Script, Alt+X)
-- Relații: FACULTATI 1-N SPECIALIZARI; FACULTATI 1-N PROFESORI;
--          SPECIALIZARI 1-N STUDENTI; SPECIALIZARI 1-N DISCIPLINE;
--          PROFESORI 1-N DISCIPLINE;
--          STUDENTI N-M DISCIPLINE (prin tabelul NOTE)
-- Toate persoanele și datele sunt fictive (generate pentru laborator).
-- Anul universitar curent: 2026-2027. Studenții din anul I nu au încă note.
-- =====================================================================

PRAGMA foreign_keys = ON;

DROP VIEW IF EXISTS v_note_complete;
DROP TABLE IF EXISTS note;
DROP TABLE IF EXISTS discipline;
DROP TABLE IF EXISTS studenti;
DROP TABLE IF EXISTS profesori;
DROP TABLE IF EXISTS specializari;
DROP TABLE IF EXISTS facultati;

CREATE TABLE facultati (
    id_facultate  INTEGER PRIMARY KEY,
    denumire      TEXT NOT NULL UNIQUE,
    oras          TEXT NOT NULL
);

CREATE TABLE specializari (
    id_specializare INTEGER PRIMARY KEY,
    denumire        TEXT    NOT NULL,
    id_facultate    INTEGER NOT NULL REFERENCES facultati(id_facultate),
    durata_ani      INTEGER NOT NULL CHECK (durata_ani IN (3, 4)),
    cod             TEXT    NOT NULL UNIQUE
);

CREATE TABLE profesori (
    id_profesor    INTEGER PRIMARY KEY,
    nume           TEXT    NOT NULL,
    prenume        TEXT    NOT NULL,
    grad_didactic  TEXT    NOT NULL,
    id_facultate   INTEGER NOT NULL REFERENCES facultati(id_facultate),
    email          TEXT    NOT NULL UNIQUE,
    an_angajare    INTEGER
);

CREATE TABLE discipline (
    id_disciplina   INTEGER PRIMARY KEY,
    denumire        TEXT    NOT NULL,
    id_specializare INTEGER NOT NULL REFERENCES specializari(id_specializare),
    an_studiu       INTEGER NOT NULL CHECK (an_studiu BETWEEN 1 AND 4),
    semestru        INTEGER NOT NULL CHECK (semestru IN (1, 2)),
    credite         INTEGER NOT NULL CHECK (credite > 0),
    id_profesor     INTEGER REFERENCES profesori(id_profesor)
);

CREATE TABLE studenti (
    id_student      INTEGER PRIMARY KEY,
    nr_matricol     TEXT    NOT NULL UNIQUE,
    nume            TEXT    NOT NULL,
    prenume         TEXT    NOT NULL,
    sex             TEXT    CHECK (sex IN ('F', 'M')),
    data_nasterii   TEXT,
    judet           TEXT,
    oras            TEXT,
    email           TEXT    NOT NULL UNIQUE,
    telefon         TEXT,
    id_specializare INTEGER NOT NULL REFERENCES specializari(id_specializare),
    an_studiu       INTEGER NOT NULL CHECK (an_studiu BETWEEN 1 AND 4),
    an_inmatriculare INTEGER NOT NULL,
    forma_invatamant TEXT   NOT NULL DEFAULT 'IF',
    bursier         INTEGER NOT NULL DEFAULT 0 CHECK (bursier IN (0, 1))
);

CREATE TABLE note (
    id_nota        INTEGER PRIMARY KEY,
    id_student     INTEGER NOT NULL REFERENCES studenti(id_student),
    id_disciplina  INTEGER NOT NULL REFERENCES discipline(id_disciplina),
    nota           INTEGER NOT NULL CHECK (nota BETWEEN 1 AND 10),
    data_examen    TEXT    NOT NULL,
    sesiune        TEXT    NOT NULL CHECK (sesiune IN ('iarnă', 'vară', 'restanțe')),
    UNIQUE (id_student, id_disciplina)
);

































































-- Verificare rapidă: numărul de rânduri din fiecare tabel.
SELECT (SELECT COUNT(*) FROM facultati) AS facultati,
       (SELECT COUNT(*) FROM specializari) AS specializari,
       (SELECT COUNT(*) FROM profesori) AS profesori,
       (SELECT COUNT(*) FROM discipline) AS discipline,
       (SELECT COUNT(*) FROM studenti) AS studenti,
       (SELECT COUNT(*) FROM note) AS note;
